"""Generate compact scientific report from audited evidence, never hand-edit data."""
import collections,json,math,statistics as st
from pathlib import Path
from common import V,load,save,sha
from prepare_rtx import root
from audit_rtx import csvwrite

def main():
    r=root();a=load(r/'analysis/ANALYSIS.json');hosts=load(r/'analysis/HOSTS.json');timed=load(r/'analysis/TIMED.json');adm=load(r/'ADMISSION.json');audit=load(r/'analysis/AUDIT.json');resource=load(r/'RESOURCE_SUMMARY.json');arc=Path(str(r)+'-archive');archive=load(arc/'ARCHIVE.json');fresh=load(arc/'FRESH_RECOMPUTE.json');out=V/'results';out.mkdir(exist_ok=True)
    coverage=[];plan=load(r/'plan.json');seen={h['task_id']:h for h in hosts};cost=[]
    for t in plan['timed_jobs']:
        c=next(c for c in plan['cells'] if c['id']==t['cell']);canonical=c['arms'][0]['name'] if t['arm']==c['arms'][1]['name'] else t['arm'];gate=adm['arms'][c['id']+'/'+canonical];h=seen.get(t['task_id']);coverage.append(dict(task_id=t['task_id'],panel=t['panel'],cell=t['cell'],arm=t['arm'],session=t['session'],block=t['block'],status='QUALIFIED' if h and h['qualified'] else 'FAILED' if h else 'NOT_STARTED_'+gate['reason'],admission=gate['reason']))
    for geom in ['B0-1023','B0-1024','T0-2','T0-4']:
        for arm in sorted({h['arm'] for h in hosts if h['stage']=='timed' and h['cell'].rsplit('-v',1)[0]==geom}):
            rows=[h for h in hosts if h['stage']=='timed' and h['cell'].rsplit('-v',1)[0]==geom and h['arm']==arm]
            cost.append(dict(geometry=geom,arm=arm,hosts=len(rows),**{k:st.mean(h[k] for h in rows) for k in ['primary_mean_us','resident_graph_mean_us','resident_call_mean_us','CPU_Q_mean_us','Q_upload_sync_mean_us','compute_return_mean_us','extra_sync_mean_us','readback_mean_us','setup_initialize_us','setup_graph_build_us','setup_allocation_us','setup_source_read_us','setup_CPU_materialize_us','setup_upload_and_sync_us','graph_buffer_bytes','persistent_input_bytes']}))
    for x in cost:
        if x['geometry'].startswith('B0'):
            x['CPU_Q_mean_us']=None;x['Q_upload_sync_mean_us']=None
    contrasts=[]
    for geom,g in a['geometries'].items():
        for label,x in g['comparisons'].items():contrasts.append(dict(geometry=geom,contrast=label,blocks=x['blocks'],sessions=x['sessions'],ratio=x['ratio'],difference_us=x['difference_us'],CI_low=x['interval'][0] if x['interval'] else None,CI_high=x['interval'][1] if x['interval'] else None,AA_scale_us=x['AA_scale_us'],threshold_us=x['threshold_us'],screen_pass=x['screen_pass']))
    for name,rows in [('COVERAGE.csv',coverage),('COST_BOUNDARIES.csv',cost),('CONTRASTS.csv',contrasts),('NUMERICAL_MISMATCHES.csv',load(r/'analysis/MISMATCHES.json'))]:csvwrite(out/name,rows)
    # Raw profile timestamps/names remain local; compact per-path kernel ranges are generated.
    tr=load(r/'trace_analysis/TRACE_HOSTS.json');import csv
    with (r/'trace_analysis/TRACE_CALLS.csv').open() as f:tc=list(csv.DictReader(f))
    trace=[]
    for h in tr:
        cr=[x for x in tc if x['task_id']==h['task_id']];formal=[x for x in cr if x['warmup']=='False'];selected=formal or cr
        trace.append(dict(attempt=h['task_id'],context=h['case_id'],layout=h['layout'],formal_replay_observed=bool(formal),observed_calls=len(selected),kernel_counts=','.join(map(str,sorted({int(x['kernels']) for x in selected}))),unmapped_records=h['unmapped_kernel_or_copy_records'],kernel_names=';'.join(h['kernel_names'])))
    csvwrite(out/'TRACE_SUMMARY.csv',trace)
    findings=dict(status='COMPLETE_WITH_NEGATIVE_QUALIFICATION',padding={k:v for k,v in adm['arms'].items() if k.startswith('B0')},screen={k:v['candidates'] for k,v in a['geometries'].items()},source_link='SOURCE_LINK_UNKNOWN',hardware='SOFTWARE_FIRST/HOLD',limits=['fixed synthetic parent inputs,not unseen prompts','single laptop,two within-day sessions','bit-exact ordinary-only admission,not mathematical truth','no decoder/actor/state qualification','failed padded paths have no admitted clean cost','kernel count is not traffic/occupancy/throughput','KV padding/setup separate,no deployment amortization claim','raw locally restored,not remotely uploaded or externally reviewed'])
    save(V/'SCIENTIFIC_FINDINGS.json',findings);save(V/'RAW_LOCATION.json',archive)
    lines=['# PR123 RTX dispatch intervention — actual result','',f"{audit['native_hosts']} native hosts, {audit['explicit_graph_calls']} explicit graph calls. UUID `{load(r/'RUN_SPEC.json')['execution_id']}` permanently closed. SOFTWARE_FIRST/HOLD.",'','Both separately started sessions and all8 planned blocks completed for eligible paths. '+str(sum(x['status']=='QUALIFIED' for x in coverage))+'/256 clean slots qualified; the other48 were never started because six cell/arm combinations failed their two-host exact-reference qualification. No scientific retry or replacement. Twelve native qualification exits3 are retained finite-output mismatches, not CUDA launch/sync failures.','', '## Reference-constrained physical intervention','', '| Logical L | Physical S | Two values × two fresh hosts | Clean eligibility |','|---|---|---|---|']
    for L in [1023,1024]:
        for delta,arm in [(0,'native_A'),(1,'pad_1'),(2,'pad_2')]:
            rows=[adm['arms'][f'B0-{L}-v{v}/{arm}'] for v in [0,1]];passed=sum(sum(load(r/'QUALIFICATION.json')[f'B0-{L}-v{v}/{arm}']['hosts']) for v in [0,1]);lines.append(f'| {L} | {L+delta} | {passed}/4 exact | '+('admitted' if all(x['eligible'] for x in rows) else 'INFEASIBLE_EXACT_REFERENCE')+' |')
    mm=load(r/'analysis/MISMATCHES.json');lines+=['',f"All {len(mm)} failed ordinary occurrences are retained with complete bytes, mismatch word count, max absolute error, signed ULP distance and first differing word in results/NUMERICAL_MISMATCHES.csv. Inputs, placement, finite values, actual node support and compute/sync returns passed. No intermediate QK/softmax/AV diagnostics were added: first internal divergence and backend cause remain UNKNOWN.",'','The only qualified padding L1023→S1025 is tested against BOTH unpadded QB controls. Padding that reaches S1024 did not preserve this reference contract, so its clean speedup is undefined. No padded serial reference replaces the unpadded two-capture-per-query reference.','', '## Actual matched clean costs','', 'Primary B0 is completed graph; primary T0 is one copy/transpose→Q upload/sync→replay/full sync→ordinary readback QPC interval. Host means equally weight the two values and8 blocks. Units µs.','', '| Geometry | Arm | Primary | Resident graph | Resident call | CPU Q | Q upload/sync | Readback |','|---|---|---:|---:|---:|---:|---:|---:|']
    for x in cost:lines.append('| '+x['geometry']+' | '+x['arm']+' | '+' | '.join(('N/A' if x['geometry'].startswith('B0') and k in ['CPU_Q_mean_us','Q_upload_sync_mean_us'] else f"{x[k]:.3f}") for k in ['primary_mean_us','resident_graph_mean_us','resident_call_mean_us','CPU_Q_mean_us','Q_upload_sync_mean_us','readback_mean_us'])+' |')
    lines+=['', 'Setup allocation, initialization, graph construction, source materialization, full initial upload and buffer bytes are in COST_BOUNDARIES.csv. B0 padding materialization CPU wall is in raw INPUT_PROVENANCE.json; it includes generation/verification and is not a deployment latency estimate. K/V/mask are resident in T0; targets preallocated; actual Q copy/transpose is charged each call. Original model-Q production remains UNKNOWN. Compute-return may already include backend synchronization; explicit subsequent full-device sync is disjoint. Neither host interval is called kernel latency.','', '## Paired estimates and prospective screen','', '| Geometry | Numerator / denominator | Ratio [95% block interval] | Δ µs | A/A scale µs | Screen |','|---|---|---|---:|---:|---|']
    for x in contrasts:
        ratio='UNKNOWN' if x['ratio'] is None else f"{x['ratio']:.6f} [{x['CI_low']:.6f}, {x['CI_high']:.6f}]";lines.append(f"| {x['geometry']} | {x['contrast']} | {ratio} | {x['difference_us']:.3f} | {x['AA_scale_us']:.3f} | {x['screen_pass']} |")
    lines+=['', 'Full per-value/per-session signs and leave-one-block-out estimates are in execution/ANALYSIS.json. Whole blocks are bootstrapped within actual sessions; arms and values stay paired, values equal weight. Inner30 calls are technical repeats. Two sessions are not independent devices or dates. No B0/T0 pooled speedup. PRACTICAL_CANDIDATE requires all8 blocks, both values and sessions in the saving direction against BOTH controls, upper interval<1 and saving>max(2% baseline,1µs,matched A/A scale).', '', 'Screen outcome: `'+json.dumps(findings['screen'],sort_keys=True)+'`. No interpretation of a tiny positive point estimate as stable acceleration.','', '## Actual path and ON evidence','',f"{audit['profile_attempts']} profiled attempts, including failed qualification paths. Actual successful capture/end/instantiate and each formal replay verified for every admitted signature; six alternating-input capability hosts verify both values for q2/q4 and both Q representations. Clean hosts do not load CUPTI and inherit mode eligibility only through exact graph/runtime signature matching. Profile timing is never pooled with clean timing. Failed paths can have only first-call direct execution evidence, not qualified steady replay. See TRACE_SUMMARY.csv and raw API/activity records.", '', 'SOURCE_LINK_UNKNOWN: candidate source mmvf even-dimension/alignment predicates and softmax launch specialization were inspected and hashed; the staged CUDA DLL lacks an authenticated source/link correspondence. Trace signatures support representation/path observations only. Padding changes work as well as dispatch. Kernel count is not traffic, occupancy, busy-time union, Tensor Core utilization or isolated causal attribution.','', '## Accounting, failures and reproducibility','',f"Native exit0 {resource['native_completed_with_exit0']}, exit3 {resource['native_failed']}; profiles {audit['profile_attempts']}/24. Native command-wall sum {resource['native_command_wall_sum_seconds']:.3f}s; stage-controller wall sum {resource['controller_stage_wall_seconds']:.3f}s; scoped native/helper/controller conservative owned upper {resource['native_helper_controller_conservative_owned_seconds']:.3f}s. Peak native Job commit {resource['peak_observed_native_Job_commit_bytes']}B, per-Job cap8GiB. Combined full-task OS peak not certified. Explicit endpoint SMI queries {resource['SMI_queries']}; all8 blocks environment-qualified. Endpoint quiet is not continuous exclusivity. Invalid/odd clock telemetry stays UNKNOWN and is not used to normalize costs.", '', 'Budget6h with final45min reserve; native120s,8GiB owned memory/output and10GiB headroom. Actual302 hosts/9228 calls are below350/11448 specifically planned and358/11732 overall caps. No models, decoder, actor, RTL, FPGA, B570, paper, main, release or automation changes.', '', 'Pre-graph failures preserved: missing build-library path, missing header path, and verifier mapping import-library/PDB names outside build/. The verifier correction was committed/frozen before any GPU query; native bytes unchanged. Initial and repair F0 both retained. No GPU startup failure or scientific retry. CPU13 unit tests,8 actual-evidence corruption negatives and4 signed-ULP diagnostics tests passed. Diagnostic signed zero-crossing ordering was corrected in an explicit offline wrapper; admission bitwise checks, frozen timing and statistics did not change. A short CPU fault-injection audit overlapped session0; all samples retained, no result-based exclusion.', '',f"Initial F0 `{sha(r/'FREEZE.json')}`; tool-repair freeze `{sha(r/'FREEZE_REPAIR1.json')}`; admission `{sha(r/'ADMISSION.json')}`.", '',f"Raw: `{r}`. ZIP: `{arc/'raw.zip'}`; {archive['members']} members, {archive['archive_bytes']}B; SHA256 `{archive['archive_sha256']}`. Member manifest SHA256 `{archive['manifest_sha256']}`. Fresh restore enumerated/hash-verified every member; a new interpreter recomputed all scientific exports byte-exact. Local verification only: raw not uploaded, no external independent review. Compact Git artifacts receive separate actual remote-byte readback.", '', '## Decision','', 'No T0 candidate meets the predeclared practical screen against both QB controls. Close the compact-QH optimization branch for these fixed inputs; no further precision hunting. The reference-preserving representation opportunity is constrained: reaching the cheap1024 path by padding does not preserve the required bytes for these inputs. The remaining admissible padding has its own matched cost estimate. T0 answers the charged ON conversion question on fixed q2/q4 synthetic inputs; follow the both-control screen and retain negative/discordant outcomes. No selector, decoder or hardware GO follows. Keep QB as the strong software baseline; software-first/HOLD remains.']
    (V/'RESULT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    print('report generated',len(cost),len(contrasts))
if __name__=='__main__':main()
